<script setup>
import { computed, ref, shallowRef } from 'vue'
import { parseRedNodes, redNodesToStl } from './redNodesToStl.js'
import { zipFiles } from '../shared/archive.js'
import { downloadFile } from '../shared/download.js'

const sources = shallowRef([])
const loading = ref(false),
  exporting = ref(false),
  error = ref(''),
  result = ref('')
const chunkSize = ref(1500),
  progress = ref(0),
  progressLabel = ref('')
const busy = computed(() => loading.value || exporting.value)
function clearResult() {
  error.value = ''
  result.value = ''
}
async function loadFiles(selected) {
  clearResult()
  sources.value = []
  const files = Array.isArray(selected) ? selected : selected ? [selected] : []
  if (!files.length) return
  loading.value = true
  try {
    sources.value = await Promise.all(
      files.map(async (file) => {
        try {
          return { name: file.name, data: parseRedNodes(await file.text()) }
        } catch (failure) {
          throw new Error(`${file.name}: ${failure.message}`, { cause: failure })
        }
      }),
    )
  } catch (failure) {
    error.value = `Could not read Red Nodes: ${failure.message}`
  } finally {
    loading.value = false
  }
}
async function exportStl() {
  if (!sources.value.length || busy.value) return
  clearResult()
  exporting.value = true
  progress.value = 0
  try {
    const files = []
    let order = 1,
      buildings = 0
    for (const source of sources.value) {
      const output = await redNodesToStl(source.data, Number(chunkSize.value), order, (done, total) => {
        progress.value = Math.round((done / total) * 100)
        progressLabel.value = `${source.name}: ${done} / ${total}`
      })
      files.push(...output.files)
      order = output.nextOrder
      buildings += output.buildings
    }
    if (!files.length) throw new Error('No usable surfaces were found.')
    downloadFile(await zipFiles(files), 'red_nodes_stl.zip', 'application/zip')
    result.value = `${buildings} buildings exported in ${files.length / 2} STL/data pairs. Downloaded: red_nodes_stl.zip.`
  } catch (failure) {
    error.value = `Could not convert Red Nodes: ${failure.message}`
  } finally {
    exporting.value = false
    progress.value = 0
    progressLabel.value = ''
  }
}
const fileUpload = ref()
</script>

<template>
  <!-- Bố cục: Form nhận nhiều JSON Red Nodes, đặt số công trình mỗi file STL và xuất ZIP; thanh tiến độ theo dõi chuyển đổi. -->
  <section>
    <h1 class="page-title">Red Nodes → STL (LBNL)</h1>
    <VaCard>
      <VaCardContent>
        <!-- Đầu vào và cấu hình xuất dùng control Vuestic; submit gọi hàm xử lý của trang, busy khóa thao tác khi đang chạy. -->
        <VaForm novalidate class="space-y-4" @submit.prevent="exportStl" @input="clearResult">
          <VaFileUpload
            id="red-nodes-files"
            v-model="fileUpload"
            type="list"
            upload-button-text="Red Nodes JSON files"
            file-types=".json,application/json"
            :disabled="busy"
            @update:modelValue="loadFiles"
          />
          <VaProgressBar v-if="loading" indeterminate aria-label="Reading file" />
          <p v-if="sources.length" class="text-sm text-secondary" data-testid="red-nodes-summary">
            {{ sources.length }} files ·
            {{ sources.reduce((sum, source) => sum + source.data.features.length, 0) }} features
          </p>
          <VaInput
            id="red-nodes-chunk-size"
            v-model="chunkSize"
            label="Buildings per STL file"
            input-aria-label="Buildings per STL file"
            type="number"
            min="1"
            step="1"
            required
            :disabled="busy"
          />
          <VaProgressBar v-if="exporting" :model-value="progress" color="primary" aria-label="Conversion progress" />
          <p v-if="progressLabel" role="status">{{ progressLabel }}</p>
          <VaButton type="submit" color="primary" :disabled="!sources.length || busy" :loading="exporting"
            >Export STL ZIP</VaButton
          >
        </VaForm>
        <!-- Thông báo đọc/xuất dữ liệu nằm gần thao tác liên quan; điều kiện v-if quyết định lúc hiển thị. -->
        <VaAlert v-if="error" color="danger" class="mt-4" role="alert" data-testid="tool-error">{{ error }}</VaAlert>
        <VaAlert v-if="result" color="success" class="mt-4" role="status" data-testid="tool-result">{{
          result
        }}</VaAlert>
      </VaCardContent>
    </VaCard>
  </section>
</template>
