import { writeAsciiSTL } from './stlio.js'

/**
 * Parse a red_nodes JSON file and check its surface vertex lists.
 * Features without surfaces remain in place so building indices stay stable.
 * Input: '{"features":[{"id":"A","properties":{"objects":[{"type":"surface","properties":{"v":[[0,0,0],[1,0,0],[0,1,0]]}}]}}]}'.
 * Output: the parsed object; malformed JSON or non-finite surface vertices throw.
 */
export function parseRedNodes(text) {
  const data = JSON.parse(text.replace(/^\uFEFF/, ''))
  if (!Array.isArray(data?.features)) throw new Error('JSON must contain a features array.')
  for (const [index, feature] of data.features.entries()) {
    if (!feature || typeof feature !== 'object') throw new Error(`Building ${index} must be an object.`)
    const objects = feature.properties?.objects ?? []
    if (!Array.isArray(objects)) throw new Error(`Building ${index} objects must be an array.`)
    for (const object of objects) {
      if (object?.type !== 'surface') continue
      const vertices = object.properties?.v
      if (
        !Array.isArray(vertices) ||
        vertices.length < 3 ||
        vertices.some((p) => !Array.isArray(p) || p.length < 3 || !p.slice(0, 3).every(Number.isFinite))
      ) {
        throw new Error(`Building ${index} has an invalid surface vertex list.`)
      }
    }
  }
  return data
}

/**
 * Triangulate surfaces in feature order and group a fixed number of buildings.
 * dataN.txt rows contain zero-based [source feature index, surface index, triangle index].
 * Surface/triangle counters continue across chunks and reset for each input file.
 * Empty features are skipped without shifting the source feature indices.
 * Input: one building A with a square surface, chunkSize 1, firstOrder 1.
 * Output: b1.stl with solid A and two facets; data1.txt is '0\t0\t0\n0\t0\t1\n'.
 */
// shortcut: fan triangulation assumes convex planar surfaces; use projected Earcut triangulation for concave surfaces.
export async function redNodesToStl(data, chunkSize = 1500, firstOrder = 1, onProgress = () => {}) {
  if (!Number.isInteger(chunkSize) || chunkSize < 1) throw new Error('Chunk size must be a positive integer.')
  const files = [],
    names = new Set()
  let solids = [],
    rows = [],
    buildings = 0,
    inChunk = 0,
    surfaceIndex = 0,
    triangleIndex = 0,
    order = firstOrder
  const flush = () => {
    if (!solids.length) return
    files.push({ name: `b${order}.stl`, content: writeAsciiSTL(solids) })
    files.push({ name: `data${order}.txt`, content: rows.map((row) => row.join('\t')).join('\n') + '\n' })
    order++
    solids = []
    rows = []
    inChunk = 0
  }
  for (const [index, feature] of data.features.entries()) {
    const positions = [],
      info = []
    for (const object of feature.properties?.objects ?? []) {
      if (object?.type !== 'surface') continue
      const vertices = object.properties.v
      for (let i = 1; i < vertices.length - 1; i++) {
        positions.push(...vertices[0].slice(0, 3), ...vertices[i].slice(0, 3), ...vertices[i + 1].slice(0, 3))
        info.push([index, surfaceIndex, triangleIndex++])
      }
      surfaceIndex++
    }
    if (info.length) {
      const name =
        String(feature.id ?? `b${index}`)
          .trim()
          .replace(/\s+/g, '_') || `b${index}`
      if (names.has(name)) throw new Error(`Duplicate solid name: ${name}.`)
      names.add(name)
      solids.push({ name, positions, count: info.length })
      rows.push(...info)
      buildings++
      inChunk++
    }
    if (inChunk >= chunkSize) flush()
    if ((index + 1) % 50 === 0 || index + 1 === data.features.length) {
      onProgress(index + 1, data.features.length)
      await new Promise((resolve) => setTimeout(resolve, 0))
    }
  }
  flush()
  return { files, buildings, nextOrder: order }
}
